    46	
    47	Parser::Parser(XRef *xrefA, Lexer *lexerA, bool allowStreamsA) {
    48	  xref = xrefA;
    49	  lexer = lexerA;
    50	  inlineImg = 0;
    51	  allowStreams = allowStreamsA;
    52	  buf1 = lexer->getObj();
